-- Source: MotherDuck thyroid_canonical_publication_v1_0.manuscript_workspace.canonical_path_malignant_events_v1_variant_clean
-- Captured: 2026-05-06 for THY-19 BQ migration

CREATE VIEW manuscript_workspace.canonical_path_malignant_events_v1_variant_clean AS WITH norm AS (SELECT e.*, lower(main."trim"(regexp_replace(COALESCE(e.histology_variant, ''), '\s+', ' ', 'g'))) AS _v FROM main.canonical_path_malignant_events_v1 AS e)SELECT n.* EXCLUDE (_v), n.histology_variant AS histology_variant_raw, CASE  WHEN (((n._v = '') OR (n._v IS NULL))) THEN (NULL) WHEN ((n._v ~~ '%diffuse sclerosing%')) THEN ('diffuse_sclerosing') WHEN (((n._v ~~ '%cribriform%morular%') OR (n._v ~~ '%cribiform%morular%') OR (n._v ~~ '%cribiform%morula%') OR (n._v ~~ '%cribriform%morula%'))) THEN ('cribriform_morular') WHEN ((n._v ~~ '%hobnail%')) THEN ('hobnail') WHEN (((n._v ~~ '%columnar cell%') OR (n._v ~~ '%columnar-cell%'))) THEN ('columnar_cell') WHEN (((n._v ~~ '%tall cell%') OR (n._v ~~ '%tall-cell%') OR (n._v ~~ '%tal cell%') OR (n._v ~~ '%tall cel %') OR (n._v ~~ '%tall cel l%') OR (n._v ~~ '%tall cell feature%'))) THEN ('tall_cell') WHEN ((n._v ~~ '%warthin%')) THEN ('warthin_like') WHEN (((n._v ~~ '%solid variant%') OR (n._v = 'solid') OR (n._v ~~ 'solid %') OR (n._v ~~ '%solid & trabecular%') OR (n._v ~~ '%solid/trabecular%'))) THEN ('solid_variant') WHEN (((n._v ~~ '%follicular sclerosing%') OR (n._v ~~ '%widely invasive%') OR (n._v ~~ '%infiltrative%'))) THEN ('follicular_variant_infiltrative') WHEN (((n._v = 'follicular') OR (n._v ~~ 'follicular %') OR (n._v ~~ '%follicular variant%') OR (n._v ~~ '%minimally invasive%') OR (n._v ~~ '%follicular growth%') OR (n._v ~~ '%macrofollicular%'))) THEN ('follicular_variant_encapsulated') WHEN (((n._v ~~ '%oncocytic%') OR (n._v ~~ '%onocytic%') OR (n._v ~~ '%hurthle%') OR (n._v ~~ '%hurthel%') OR (n._v = 'oxyphilic') OR (n._v ~~ 'oxyphilic %'))) THEN ('oncocytic') WHEN ((n._v ~~ '%insular%')) THEN ('insular') WHEN (((n._v ~~ '%microcarcinoma%') OR (n._v ~~ '%microcarcioma%') OR (n._v ~~ '%micorcarcinoma%') OR (n._v ~~ '%microcarinoma%') OR (n._v ~~ '%microcaarcinoma%') OR (n._v ~~ '%microcaricnoma%') OR (n._v ~~ '%microcarcinooma%'))) THEN ('microcarcinoma') WHEN (((n._v ~~ '%folliucalr%') OR (n._v ~~ '%follicualr%'))) THEN ('follicular_variant_encapsulated') WHEN ((n._v ~~ '%collumnar%')) THEN ('columnar_cell') WHEN (((n._v ~~ '%classical%') OR (n._v ~~ '%classic %') OR (n._v = 'classic') OR (n._v ~~ '%classsical%') OR (n._v = 'ptc'))) THEN ('classical') ELSE 'other' END AS histology_variant_clean FROM norm AS n;
